using System.Globalization;using System.IO.Compression;using WAID.Application.Services;namespace WAID.Infrastructure.Persistence;public sealed class SqliteSnapshotComponentProvider(WaidDatabase database,string name,string version,IReadOnlyDictionary<string,string>queries):ISystemSnapshotComponentProvider{public string Name=>name;public string SerializerVersion=>version;public async Task<IReadOnlyDictionary<string,string>>CaptureAsync(CancellationToken token){var values=new Dictionary<string,string>(StringComparer.Ordinal);await using var c=database.OpenConnection();foreach(var item in queries){await using var q=c.CreateCommand();q.CommandText=item.Value;var value=await q.ExecuteScalarAsync(token);values[item.Key]=Convert.ToString(value,CultureInfo.InvariantCulture)??"Unavailable";}return values;}}
public sealed class SqliteDigitalTwinRepository(WaidDatabase database):IDigitalTwinRepository{private static readonly System.Text.Json.JsonSerializerOptions Json=new(System.Text.Json.JsonSerializerDefaults.Web);public async Task SaveAsync(DigitalTwinSnapshot x,byte[]payload,CancellationToken t){await using var c=database.OpenConnection();await using var q=c.CreateCommand();q.CommandText="INSERT INTO digital_twin_snapshots(id,captured_utc,purpose,is_pinned,repair_transaction_id,related_snapshot_id,integrity_sha256,metadata_json,compressed_payload)VALUES($id,$time,$purpose,$pin,$repair,$related,$hash,$json,$payload)";q.Parameters.AddWithValue("$id",x.Id.ToString());q.Parameters.AddWithValue("$time",x.CapturedAtUtc.ToString("O"));q.Parameters.AddWithValue("$purpose",(int)x.Purpose);q.Parameters.AddWithValue("$pin",x.IsPinned?1:0);q.Parameters.AddWithValue("$repair",x.RepairTransactionId is null?DBNull.Value:x.RepairTransactionId.Value.ToString());q.Parameters.AddWithValue("$related",x.RelatedSnapshotId is null?DBNull.Value:x.RelatedSnapshotId.Value.ToString());q.Parameters.AddWithValue("$hash",x.IntegritySha256);q.Parameters.AddWithValue("$json",System.Text.Json.JsonSerializer.Serialize(new{x.SchemaVersion,ComponentCount=x.Components.Count},Json));q.Parameters.AddWithValue("$payload",payload);await q.ExecuteNonQueryAsync(t);}public async Task<IReadOnlyList<DigitalTwinSnapshot>>GetRecentAsync(int count,CancellationToken t){if(count is<1 or>500)throw new ArgumentOutOfRangeException(nameof(count));var list=new List<DigitalTwinSnapshot>();await using var c=database.OpenConnection();await using var q=c.CreateCommand();q.CommandText="SELECT compressed_payload FROM digital_twin_snapshots ORDER BY captured_utc DESC LIMIT $count";q.Parameters.AddWithValue("$count",count);await using var r=await q.ExecuteReaderAsync(t);while(await r.ReadAsync(t))list.Add(Decode((byte[])r[0]));return list;}public async Task<DigitalTwinSnapshot?>GetAsync(Guid id,CancellationToken t){await using var c=database.OpenConnection();await using var q=c.CreateCommand();q.CommandText="SELECT compressed_payload FROM digital_twin_snapshots WHERE id=$id";q.Parameters.AddWithValue("$id",id.ToString());var payload=await q.ExecuteScalarAsync(t)as byte[];return payload is null?null:Decode(payload);}public async Task SaveDiffAsync(SystemSnapshotDiff x,CancellationToken t){await using var c=database.OpenConnection();await using var q=c.CreateCommand();q.CommandText="INSERT INTO digital_twin_diffs(id,before_id,after_id,compared_utc,diff_json)VALUES($id,$before,$after,$time,$json)";q.Parameters.AddWithValue("$id",x.Id.ToString());q.Parameters.AddWithValue("$before",x.BeforeId.ToString());q.Parameters.AddWithValue("$after",x.AfterId.ToString());q.Parameters.AddWithValue("$time",x.ComparedAtUtc.ToString("O"));q.Parameters.AddWithValue("$json",System.Text.Json.JsonSerializer.Serialize(x,Json));await q.ExecuteNonQueryAsync(t);}public async Task<SnapshotRetentionResult>ApplyRetentionAsync(DateTimeOffset retain,CancellationToken t){await using var c=database.OpenConnection();await using var count=c.CreateCommand();count.CommandText="SELECT COUNT(*) FROM digital_twin_snapshots WHERE is_pinned=1";var pinned=Convert.ToInt32(await count.ExecuteScalarAsync(t));await using var q=c.CreateCommand();q.CommandText="DELETE FROM digital_twin_snapshots WHERE is_pinned=0 AND captured_utc<$retain";q.Parameters.AddWithValue("$retain",retain.ToString("O"));var deleted=await q.ExecuteNonQueryAsync(t);var result=new SnapshotRetentionResult(DateTimeOffset.UtcNow,(int)Math.Max(0,(DateTimeOffset.UtcNow-retain).TotalDays),deleted,pinned,"snapshot-retention-v1");await using var save=c.CreateCommand();save.CommandText="INSERT INTO digital_twin_retention_jobs(id,executed_utc,result_json)VALUES($id,$time,$json)";save.Parameters.AddWithValue("$id",Guid.NewGuid().ToString());save.Parameters.AddWithValue("$time",result.ExecutedAtUtc.ToString("O"));save.Parameters.AddWithValue("$json",System.Text.Json.JsonSerializer.Serialize(result,Json));await save.ExecuteNonQueryAsync(t);return result;}private static DigitalTwinSnapshot Decode(byte[] payload){using var source=new MemoryStream(payload,false);using var gzip=new GZipStream(source,CompressionMode.Decompress);return System.Text.Json.JsonSerializer.Deserialize<DigitalTwinSnapshot>(gzip,Json)??throw new InvalidDataException("Invalid snapshot.");}}
